export function Csr({
  bundleSize = {{bundleSize}},
  stage = "{{stage}}",
  accent = "{{accent}}",
  showTimes = {{showTimes}},
}) {
  const steps = [
    { id: "blank", label: "Blank HTML", time: "0ms" },
    { id: "loading", label: `Download ${bundleSize}KB JS`, time: "~600ms" },
    { id: "rendered", label: "Render + hydrate", time: "~900ms" },
  ];
  const previews = { blank: "\u00A0", loading: "\u25F0", rendered: "Page content" };
  return (
    <div role="img" aria-label={`CSR timeline, currently at ${stage}`} style={{ font: "12px/1.5 system-ui, sans-serif", color: "#241430", background: "#FAF7F2", padding: 16, borderRadius: 12, width: 320, boxSizing: "border-box" }}>
      <div style={{ display: "flex", gap: 6, marginBottom: 14 }}>
        {steps.map((s) => (
          <span key={s.id} style={{ flex: 1, textAlign: "center", padding: "8px 4px", borderRadius: 8, fontSize: 10, fontWeight: 600, opacity: s.id === stage ? 1 : .4, background: s.id === stage ? accent : "#24143010" }}>
            {s.label}
            {showTimes && <small style={{ display: "block", fontWeight: 400, color: "#24143099", marginTop: 3 }}>{s.time}</small>}
          </span>
        ))}
      </div>
      <div style={{ height: 56, display: "grid", placeItems: "center", background: "#ffffff", border: "1.5px dashed #24143020", borderRadius: 8, fontSize: 20, fontWeight: 700, color: stage === "rendered" ? accent : "#241430" }}>{previews[stage]}</div>
    </div>
  );
}
